import { useQuery } from "@tanstack/react-query";
import { Equal, Expect } from "../helpers/type-utils";

interface User {
  fullName: string;
  job: string;
}

const getUser = async (): Promise<User> => {
  return Promise.resolve({
    fullName: "Matt Pocock",
    job: "Developer",
  });
};

/**
 * A bit of a hint to start with. useQuery has a LOT of overloads - but a lot
 * of them are disappearing in the next major version. The ones that'll be
 * sticking around are the first three.
 *
 * 1. How are the first three overloads different to the others? Put differently,
 * what's the thing that's similar about the first three that's different to
 * the other six?
 */

useQuery;
// ^ CMD+click on this to see the overloads

/**
 * 2. When you provide queryFn to useQuery, the type of query.data is inferred
 * as the return type of queryFn. Why is that?
 */
const query1 = useQuery({
  queryFn: getUser,
});

// Without initialData, the type of query1.data is User | undefined
type test1 = Expect<Equal<typeof query1.data, User | undefined>>;

/**
 * 3. When you provide initialData to useQuery, the type of query.data no longer
 * has undefined in it. Why is that?
 */
const query2 = useQuery({
  queryFn: getUser,
  initialData: {
    fullName: "",
    job: "",
  },
});

// WITH initialData, the type of query.data is just User
type test2 = Expect<Equal<typeof query2.data, User>>;

import {
  useQuery,
  QueryKey,
  QueryFunctionContext,
} from "@tanstack/react-query";
import { useAuthToken } from "fake-external-lib";
import { Equal, Expect } from "../helpers/type-utils";

const useApi = <TQueryKey extends QueryKey, TQueryFnData>(
  queryKey: TQueryKey,
  queryFn: (
    ctx: QueryFunctionContext<TQueryKey>,
    token: string,
  ) => Promise<TQueryFnData>,
) => {
  const token = useAuthToken();

  return useQuery({
    queryFn: (ctx) => queryFn(ctx, token),
    queryKey,
  });
};

// If you pass in an array of strings to queryFn, the type of ctx.queryKey
// should be string[]
const query = useApi(["users"], async (ctx, token) => {
  type tests = [
    Expect<Equal<typeof ctx.queryKey, string[]>>,
    Expect<Equal<typeof token, string>>,
  ];

  return Promise.resolve([
    {
      id: 1,
      name: "Matt Pocock",
    },
  ]);
});

// The type of query.data should be { id: number; name: string }[] | undefined
type tests = [
  Expect<Equal<typeof query.data, { id: number; name: string }[] | undefined>>,
];

// If you pass in an array of numbers in the queryKey, the type of ctx.queryKey
// should be number[]
useApi([1, 2], async (ctx, token) => {
  type tests = [
    Expect<Equal<typeof ctx.queryKey, number[]>>,
    Expect<Equal<typeof token, string>>,
  ];
});

import { FieldValues, useForm } from "react-hook-form";
import { Equal, Expect } from "../helpers/type-utils";

/**
 * 1. When you provide default values to useForm, the return type of getValues
 * gets inferred as the shape of those values.
 *
 * Investigate why this is, and what TFieldValues is being used for.
 */
const Example1 = () => {
  const form = useForm({
    defaultValues: {
      firstName: "",
      lastName: "",
    },
  });

  return (
    <form
      onSubmit={form.handleSubmit((values) => {
        type test = Expect<
          Equal<typeof values, { firstName: string; lastName: string }>
        >;
      })}
    >
      <input {...form.register("firstName")} />
      <input {...form.register("lastName")} />
    </form>
  );
};

/**
 * 2. When you don't pass a default value, the return type of getValues is
 * inferred as FieldValues.
 *
 * Investigate why this is, and what type FieldValues is.
 */

const Example2 = () => {
  const form = useForm();

  return (
    <form
      onSubmit={form.handleSubmit((values) => {
        type test = Expect<Equal<typeof values, FieldValues>>;
      })}
    >
      <input {...form.register("firstName")} />
      <input {...form.register("lastName")} />
    </form>
  );
};

/**
 * 3. If we don't pass default values, how do we get
 * react-hook-form to understand what type our fields are?
 */

type FormValues = {
  firstName: string;
  lastName: string;
};

const Example3 = () => {
  const form = useForm<FormValues>();

  return (
    <form
      onSubmit={form.handleSubmit((values) => {
        type test = Expect<Equal<typeof values, FormValues>>;
      })}
    >
      <input {...form.register("firstName")} />
      <input {...form.register("lastName")} />
      {/* @ts-expect-error */}
      <input {...form.register("middleName")} />
    </form>
  );
};

export type Expect<T extends true> = T;
export type ExpectTrue<T extends true> = T;
export type ExpectFalse<T extends false> = T;
export type IsTrue<T extends true> = T;
export type IsFalse<T extends false> = T;

export type Equal<X, Y> = (<T>() => T extends X ? 1 : 2) extends <
  T,
>() => T extends Y ? 1 : 2
  ? true
  : false;
export type NotEqual<X, Y> = true extends Equal<X, Y> ? false : true;

// https://stackoverflow.com/questions/49927523/disallow-call-with-any/49928360#49928360
export type IsAny<T> = 0 extends 1 & T ? true : false;
export type NotAny<T> = true extends IsAny<T> ? false : true;

export type Debug<T> = { [K in keyof T]: T[K] };
export type MergeInsertions<T> = T extends object
  ? { [K in keyof T]: MergeInsertions<T[K]> }
  : T;

export type Alike<X, Y> = Equal<MergeInsertions<X>, MergeInsertions<Y>>;

/**
 * Expect that one type is assignable to another.
 *
 * @example
 *
 * type tests = [
 *   // Expect that `number` is assignable to `1`.
 *   Expect<Extends<1, number>>,
 *   // Expect that `abc` is assignable to `string`
 *   Expect<Extends<'abc', string>>,
 * ];
 */
export type Extends<VALUE, EXPECTED> = EXPECTED extends VALUE ? true : false;
export type ExpectValidArgs<
  FUNC extends (...args: any[]) => any,
  ARGS extends any[],
> = ARGS extends Parameters<FUNC> ? true : false;

export type UnionToIntersection<U> = (
  U extends any ? (k: U) => void : never
) extends (k: infer I) => void
  ? I
  : never;

